function t(key) {
    return (I18N[currentLang] && I18N[currentLang][key]) || I18N.it[key];
}

function getLocalizedExercise(idx) {
    const base = exercises[idx];
    if (currentLang === 'it' || !EXERCISES_I18N[currentLang]) return base;
    const loc = EXERCISES_I18N[currentLang][idx];
    return {
        ...base,
        badge: loc.badge,
        title: loc.title,
        desc: loc.desc,
        hint: loc.hint,
        verify: (objs) => {
            const res = base.verify(objs);
            return { ok: res.ok, msg: res.ok ? loc.okMsg : loc.koMsg };
        }
    };
}
